// TIVRA News — Provider Statistics Audit Script
// Reports exact breakdown of articles generated by each AI provider.

import fs from "node:fs";
import path from "node:path";

const REGISTRY_PATH = path.resolve("data/published-registry.json");

if (!fs.existsSync(REGISTRY_PATH)) {
  console.error("Registry file not found at:", REGISTRY_PATH);
  process.exit(1);
}

const registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, "utf8"));
const today = new Date().toISOString().slice(0, 10);

const totalArticles = Object.keys(registry).length;
const todayArticles = Object.entries(registry).filter(([_, v]) => v.d === today);

function summarizeProviders(entries) {
  const counts = {};
  for (const [_, v] of entries) {
    const p = v.p || "gemini (primary)";
    counts[p] = (counts[p] || 0) + 1;
  }
  return counts;
}

const todayStats = summarizeProviders(todayArticles);
const allStats = summarizeProviders(Object.entries(registry));

console.log("=============================================================");
console.log("            TIVRA NEWS — AI PROVIDER AUDIT REPORT            ");
console.log("=============================================================");
console.log(`Current Date:       ${today}`);
console.log(`Articles Today:     ${todayArticles.length}`);
console.log(`Total In Registry:  ${totalArticles}`);
console.log("-------------------------------------------------------------");
console.log("PROVIDER BREAKDOWN FOR TODAY:");
for (const [provider, count] of Object.entries(todayStats)) {
  const pct = ((count / (todayArticles.length || 1)) * 100).toFixed(1);
  console.log(`  • ${provider.padEnd(28)} : ${count.toString().padStart(5)} articles (${pct}%)`);
}

console.log("-------------------------------------------------------------");
console.log("LIFETIME / OVERALL PROVIDER USAGE:");
for (const [provider, count] of Object.entries(allStats)) {
  const pct = ((count / totalArticles) * 100).toFixed(1);
  console.log(`  • ${provider.padEnd(28)} : ${count.toString().padStart(5)} articles (${pct}%)`);
}
console.log("=============================================================");
